<script setup lang="ts">
import ServerTable from "../../components/ServerTable.vue";
import ActionMenu from "../../components/ActionMenu.vue";
import { Head, Link, router, usePage } from '@inertiajs/vue3';
import { computed, reactive } from 'vue';
import type { SharedProps } from '../../types';
import AppLayout from '../../layouts/AppLayout.vue';
import type { PageRows as Page } from '../../types/salesOrder';
import { money } from '../../types/salesOrder';
const props=defineProps<{rows:Page<{id:number;nomor:string;tanggal:string;siapa:string;invoice:string;so:string;alasan:string;status:string;nominal_tagihan:string;nominal_refund:string|null}>;filters:{q?:string;status?:string};pending:number}>();
const filter=reactive({q:props.filters.q||'',status:props.filters.status||''});
const page = usePage<SharedProps>();
const canSalesOrder = computed(() => page.props.permissions.sales_order?.includes('View'));
</script>
<template><Head title="Refund"/><AppLayout title="Refund"><header class="page-header"><h1>Sales Order</h1></header><nav class="tabs" aria-label="Jenis dokumen"><Link v-if="canSalesOrder" href="/sales-order">Sales Order</Link><Link v-if="canSalesOrder" href="/sales-order?tab=surat">Surat Kerja Trainer</Link><Link href="/sales-order/refund" aria-current="page">Refund ({{pending}} menunggu)</Link></nav><p>Refund terbentuk dari peserta/company dengan Invoice lunas yang diproses tidak ikut setelah Reschedule.</p><form class="filters" @submit.prevent="router.get('/sales-order/refund',filter)"><label>Status<select v-model="filter.status"><option value="">Semua</option><option value="menunggu">Menunggu Finance</option><option value="selesai">Selesai</option></select></label><button>Cari</button></form><ServerTable url="/sales-order/refund/data" label="Refund" :columns='[{"title": "No", "orderable": false, "className": ""}, {"title": "Nomor Refund", "orderable": true, "className": ""}, {"title": "Peserta / Company", "orderable": false, "className": ""}, {"title": "Sales Order", "orderable": false, "className": ""}, {"title": "Invoice", "orderable": false, "className": ""}, {"title": "Nominal", "orderable": true, "className": "dt-body-right"}, {"title": "Status", "orderable": true, "className": ""}, {"title": "Action", "orderable": false, "className": ""}]' :filters="{ ...filters }" refresh-on-visit ><template #cell-0="{ row: p, number }">{{ number }}</template><template #cell-1="{ row: p, number }">{{ p.nomor }}<small>{{ p.tanggal }}</small></template><template #cell-2="{ row: p, number }">{{ p.siapa }}<small>{{ p.alasan }}</small></template><template #cell-3="{ row: p, number }">{{ p.so }}</template><template #cell-4="{ row: p, number }">{{ p.invoice }}</template><template #cell-5="{ row: p, number }">{{ money(p.nominal_tagihan) }}<small v-if="p.nominal_refund">Refund {{ money(p.nominal_refund) }}</small></template><template #cell-6="{ row: p, number }"><span class="badge" 